/** Bundled UI only: credentials stay native and the bridge is restricted to record routes. */
public class CaptureActivity extends Activity {
 private WebView web;
 private final ExecutorService io=Executors.newSingleThreadExecutor();
 private final Handler handler=new Handler();
 private Credentials credentials;
 private ValueCallback<Uri[]> picker;
 private JSONObject pendingPermission,pendingPhoto;
 private File photoFile;
 private MediaRecorder recorder;
 private File segment;
 private File mediaRoot;
 private boolean recording;
 private final Runnable rotate=new Runnable(){public void run(){if(!recording)return;try{stopSegment();startSegment();handler.postDelayed(this,10000);}catch(Exception e){recording=false;stopSegment();}}};
 @Override public void onCreate(Bundle state){super.onCreate(state);credentials=new Credentials(this);mediaRoot=new File(getFilesDir(),"capture-media");mediaRoot.mkdirs();
  web=new WebView(this);setContentView(web);web.setBackgroundColor(Appearance.background(this));WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setTextZoom(Math.round(getResources().getConfiguration().fontScale*100));settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);
  web.addJavascriptInterface(new Object(){@JavascriptInterface public void postMessage(String message){io.execute(()->{try{dispatch(new JSONObject(message));}catch(Exception ignored){}});}},"CaptureNative");
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri link=request.getUrl();if(request.hasGesture()&&("https".equals(link.getScheme())||"http".equals(link.getScheme()))&&!"capture.local".equals(link.getHost())){try{startActivity(new Intent(Intent.ACTION_VIEW,link));}catch(Exception ignored){}}return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri uri=request.getUrl();if(!"https".equals(uri.getScheme())||!"capture.local".equals(uri.getHost()))return new WebResourceResponse("text/plain","utf-8",new ByteArrayInputStream(new byte[0]));String resource=uri.getPath();if(resource!=null&&resource.matches("/writing/(index[.]html|bridge[.]js|writing[.](js|css)|assets/[a-zA-Z0-9_.-]+)")){try{return new WebResourceResponse(resource.endsWith(".js")?"application/javascript":resource.endsWith(".css")?"text/css":resource.endsWith(".png")?"image/png":"text/html","utf-8",getAssets().open("capture"+resource));}catch(IOException e){return new WebResourceResponse("text/plain","utf-8",new ByteArrayInputStream(new byte[0]));}}String name=uri.getLastPathSegment();if(!Arrays.asList("index.html","capture.js","capture.css","store.js","bridge.js","brand.png","processing.html","processing-center.js","processing-center.css","processing-shell.js","processing-notice.js","processing-shell.css","processing-marked.js","processing-purify.js","processing-library.png","processing-collect.png","processing-person.png").contains(name))return null;try{return localResource(name);}catch(IOException e){return null;}}});
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(picker!=null)picker.onReceiveValue(null);picker=callback;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/jpeg","image/png","image/webp","image/gif","audio/*"}).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);try{startActivityForResult(intent,82);return true;}catch(Exception e){picker.onReceiveValue(null);picker=null;return false;}}});
  web.loadUrl(getIntent().getBooleanExtra("writing",false)?"https://capture.local/writing/index.html#/writing":"https://capture.local/"+(getIntent().getBooleanExtra("processing",false)?"processing.html"+(getIntent().hasExtra("processingTask")?"?task="+Uri.encode(getIntent().getStringExtra("processingTask")):""):"index.html"));
 }
 private WebResourceResponse localResource(String name)throws IOException {
  InputStream input=getAssets().open("capture/"+name);
  if(name.equals("processing.html")){
   ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream source=input){byte[] chunk=new byte[8192];int length;while((length=source.read(chunk))!=-1)bytes.write(chunk,0,length);}
   String theme=Appearance.dark(this)?"dark":"light";
   String html=new String(bytes.toByteArray(),StandardCharsets.UTF_8).replace("<body>","<body data-theme=\""+theme+"\">").replace("<main id=\"processing\">","<main id=\"processing\" data-theme=\""+theme+"\">");
   input=new ByteArrayInputStream(html.getBytes(StandardCharsets.UTF_8));
  }
  return new WebResourceResponse(name.endsWith(".js")?"application/javascript":name.endsWith(".css")?"text/css":name.endsWith(".png")?"image/png":"text/html","utf-8",input);
 }
 private void reply(JSONObject request,Object value,String error){try{JSONObject result=new JSONObject().put("id",request.getString("id"));if(error!=null)result.put("error",error);else result.put("value",value==null?JSONObject.NULL:value);runOnUiThread(()->{if(web!=null)web.evaluateJavascript("window.captureReply("+result.toString()+")",null);});}catch(Exception ignored){}}
 private void dispatch(JSONObject request){try{String action=request.getString("action");Object result;
  if(action.equals("status")){Credentials.Snapshot c=credentials.snapshot();result=new JSONObject().put("paired",c!=null).put("server",c==null?credentials.lastOrigin():c.server).put("deviceId",c==null?"":c.deviceId).put("nativeMedia",true).put("theme",Appearance.dark(this)?"dark":"light");}
  else if(action.equals("request"))result=network(request.getJSONObject("input"));
  else if(action.equals("navigate")){String target=request.getString("input");if(target.equals("writing")){runOnUiThread(()->web.loadUrl("https://capture.local/writing/index.html#/writing"));reply(request,new JSONObject(),null);return;}
   Intent nativePage=new Intent(this,store.inspirai.library.nativeui.NativeActivity.class);
   if(target.equals("share"))nativePage.putExtra("route","share:"+UUID.randomUUID());
   else if(target.matches("task:[a-f0-9-]{36}"))nativePage.putExtra("route",target).putExtra("tab","tasks");
   else if(Arrays.asList("record","library","tasks","settings").contains(target))nativePage.putExtra("tab",target.equals("record")?"records":target.equals("settings")?"account":target);
   else throw new Exception("页面无效");
   runOnUiThread(()->{startActivity(nativePage);finish();});result=new JSONObject();}
  else if(action.equals("export")){JSONObject input=request.getJSONObject("input");String name=input.getString("name");if(name.contains("/")||name.contains("\\")||name.length()>105||!(name.endsWith(".html")||name.endsWith(".zip")))throw new Exception("导出文件名无效");byte[] bytes=Base64.decode(input.getString("bytes"),Base64.NO_WRAP);if(bytes.length>64*1024*1024)throw new Exception("文章包过大");File folder=new File(getCacheDir(),"writing-export");folder.mkdirs();File file=new File(folder,name);try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);}Uri uri=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".capture",file);runOnUiThread(()->startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType(name.endsWith(".html")?"text/html":"application/zip").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"导出文章")));result=new JSONObject();}
  else if(action.equals("recover"))result=new JSONObject().put("files",recover());
  else if(action.equals("mediaAck")){String id=request.getString("input");if(!id.matches("[0-9a-fA-F-]{36}"))throw new Exception("媒体编号无效");File[] files=mediaRoot.listFiles();if(files!=null)for(File file:files)if(file.getName().startsWith(id+"."))file.delete();result=new JSONObject();}
  else if(action.equals("recordStart")||action.equals("photo")){runOnUiThread(()->permission(request,action.equals("recordStart")?Manifest.permission.RECORD_AUDIO:Manifest.permission.CAMERA));return;}
  else if(action.equals("recordStop")){runOnUiThread(()->{recording=false;handler.removeCallbacks(rotate);stopSegment();io.execute(()->{try{reply(request,new JSONObject().put("files",recover()),null);}catch(Exception e){reply(request,null,e.getMessage());}});});return;}
  else throw new Exception("不支持的操作");reply(request,result,null);
 }catch(Exception e){reply(request,null,e.getMessage());}}
 private static boolean allowed(String path,String method){boolean writing=method.equals("GET")&&(path.matches("/api/writing/(sessions|styles|entries)")||path.matches("/api/writing/sessions/[a-f0-9-]{36}(/drafts/[a-f0-9-]{36}(/files/[a-f0-9]{64})?|/files/[a-f0-9-]{36}|/history)?"))||method.equals("POST")&&(path.equals("/api/writing/sessions")||path.matches("/api/writing/sessions/[a-f0-9-]{36}/(answers|turns|materials|discuss|start|style|revise)"));boolean processing=method.equals("GET")&&(path.equals("/api/processing-center")||path.matches("/api/tasks/[a-f0-9-]{36}/trial-report"))||method.equals("POST")&&(path.matches("/api/processing-center/items/[a-zA-Z0-9-]+")||path.matches("/api/tasks/[a-f0-9-]{36}/(trial-choice|trial-rerun)"));return processing||writing||method.equals("GET")&&(path.equals("/api/state")||path.equals("/api/records")||path.matches("/api/records/[a-zA-Z0-9-]+")||path.matches("/api/records/media/[a-f0-9]{64}")||path.matches("/api/tasks/[a-zA-Z0-9-]+/draft"))||method.equals("PUT")&&(path.matches("/api/records/[a-zA-Z0-9-]+")||path.matches("/api/records/media/[a-f0-9]{64}"))||method.equals("POST")&&(path.matches("/api/records/[a-zA-Z0-9-]+/process")||path.matches("/api/tasks/[a-zA-Z0-9-]+/(approve|retry|cancel)"));}
 private static boolean binaryRead(String route,String method){return method.equals("GET")&&(route.matches("/api/records/media/[a-f0-9]{64}")||route.matches("/api/writing/sessions/[a-f0-9-]{36}(/files/[a-f0-9-]{36}|/drafts/[a-f0-9-]{36}/files/[a-f0-9]{64})"));}
 private JSONObject network(JSONObject input)throws Exception{Credentials.Snapshot c=credentials.snapshot();if(c==null)throw new Exception("请先连接资料空间，记录已保存在本机");String expected=input.optString("server");if(!expected.isEmpty()&&!expected.equals(c.server))throw new Exception("此记录属于另一资料空间，请恢复原连接");String expectedDevice=input.optString("deviceId");if(!expectedDevice.isEmpty()&&!expectedDevice.equals(c.deviceId))throw new Exception("资料空间已切换，本机输入仍保留");String route=input.getString("route"),method=input.optString("method","GET");if(!allowed(route,method))throw new Exception("接口无效");HttpURLConnection connection=(HttpURLConnection)new URL(c.server+route).openConnection();try{connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(120000);connection.setRequestMethod(method);connection.setRequestProperty("Authorization","Bearer "+c.token);
  if(input.has("bytes")||input.has("json")){byte[] bytes=input.has("bytes")?Base64.decode(input.getString("bytes"),Base64.NO_WRAP):input.getJSONObject("json").toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>32*1024*1024)throw new Exception("附件超过32 MiB");connection.setDoOutput(true);connection.setRequestProperty("Content-Type",input.has("bytes")?input.getString("mime"):"application/json");connection.setFixedLengthStreamingMode(bytes.length);try(OutputStream output=connection.getOutputStream()){output.write(bytes);}}
  int code=connection.getResponseCode();byte[] bytes;try(InputStream stream=code<400?connection.getInputStream():connection.getErrorStream()){bytes=read(stream,64*1024*1024);}Credentials.Snapshot live=credentials.snapshot();if(live==null||!c.generation.equals(live.generation)||!c.token.equals(live.token)||!c.server.equals(live.server))throw new Exception("登录状态已改变，本机记录保留");String mime=connection.getContentType();JSONObject result=new JSONObject().put("status",code);if(mime!=null&&mime.startsWith("application/json")&&!(code>=200&&code<300&&binaryRead(route,method)))result.put("json",new JSONObject(new String(bytes,StandardCharsets.UTF_8)));else result.put("bytes",Base64.encodeToString(bytes,Base64.NO_WRAP)).put("mime",mime==null?"application/octet-stream":mime);return result;
 }finally{connection.disconnect();}}
 private static byte[] read(InputStream input,int limit)throws Exception{ByteArrayOutputStream output=new ByteArrayOutputStream();if(input==null)return new byte[0];byte[] chunk=new byte[8192];int count;while((count=input.read(chunk))!=-1){if(output.size()+count>limit)throw new Exception("文件过大");output.write(chunk,0,count);}return output.toByteArray();}
 private void permission(JSONObject request,String permission){if(checkSelfPermission(permission)==PackageManager.PERMISSION_GRANTED){performMedia(request);return;}pendingPermission=request;requestPermissions(new String[]{permission},83);}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==83&&pendingPermission!=null){JSONObject request=pendingPermission;pendingPermission=null;if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)performMedia(request);else reply(request,null,"权限未允许，可以继续输入文字或导入文件");}}
 private void performMedia(JSONObject request){try{if(request.getString("action").equals("recordStart")){if(recording)throw new Exception("录音已开始");recording=true;startSegment();handler.postDelayed(rotate,10000);reply(request,new JSONObject(),null);}else{pendingPhoto=request;photoFile=new File(mediaRoot,UUID.randomUUID()+".camera");Uri uri=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".capture",photoFile);Intent intent=new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE).putExtra(android.provider.MediaStore.EXTRA_OUTPUT,uri).addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(intent,84);}}catch(Exception e){recording=false;reply(request,null,e.getMessage());}}
 private void startSegment()throws Exception{segment=new File(mediaRoot,UUID.randomUUID()+".active");recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setOutputFile(segment.getAbsolutePath());recorder.prepare();recorder.start();}
 private void stopSegment(){if(recorder==null)return;boolean complete=false;try{recorder.stop();complete=true;}catch(RuntimeException ignored){}finally{recorder.release();recorder=null;}if(complete)segment.renameTo(new File(mediaRoot,segment.getName().replace(".active",".m4a")));}
 private JSONArray recover()throws Exception{JSONArray files=new JSONArray();File[] saved=mediaRoot.listFiles();if(saved!=null){Arrays.sort(saved,Comparator.comparingLong(File::lastModified).thenComparing(File::getName));for(File file:saved)if(file.getName().endsWith(".m4a")||file.getName().endsWith(".jpg")){String id=file.getName().substring(0,36);try(InputStream input=new FileInputStream(file)){files.put(new JSONObject().put("id",id).put("name",file.getName()).put("mime",file.getName().endsWith(".jpg")?"image/jpeg":"audio/mp4").put("bytes",Base64.encodeToString(read(input,32*1024*1024),Base64.NO_WRAP)));}}}return files;}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==82&&picker!=null){Uri[] values=null;if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){values=new Uri[data.getClipData().getItemCount()];for(int i=0;i<values.length;i++)values[i]=data.getClipData().getItemAt(i).getUri();}else if(data.getData()!=null)values=new Uri[]{data.getData()};}picker.onReceiveValue(values);picker=null;}if(code==84&&pendingPhoto!=null){JSONObject request=pendingPhoto;pendingPhoto=null;if(result!=RESULT_OK){reply(request,null,null);return;}try{if(photoFile==null||photoFile.length()==0)throw new Exception("相机未返回照片");File file=new File(mediaRoot,photoFile.getName().replace(".camera",".jpg"));if(!photoFile.renameTo(file))throw new Exception("无法保存照片");io.execute(()->{try{JSONArray files=recover();for(int i=0;i<files.length();i++){JSONObject saved=files.getJSONObject(i);if(saved.getString("name").equals(file.getName())){reply(request,saved,null);return;}}}catch(Exception e){reply(request,null,e.getMessage());}});}catch(Exception e){reply(request,null,e.getMessage());}}}
 @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){web.evaluateJavascript("Boolean(window.captureBack && window.captureBack())",value->{if(!"true".equals(value)){if(web.canGoBack())web.goBack();else finish();}});}
 @Override protected void onPause(){super.onPause();if(recording){recording=false;handler.removeCallbacks(rotate);stopSegment();}}
 @Override protected void onDestroy(){handler.removeCallbacks(rotate);recording=false;stopSegment();if(picker!=null)picker.onReceiveValue(null);if(web!=null){web.removeJavascriptInterface("CaptureNative");web.destroy();web=null;}io.shutdown();super.onDestroy();}
}
